use vstd::prelude::*;

verus! {
    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        ensures
            result.len() == a.len(),
            forall |i: nat| 0 <= i < a.len() ==> result[i] == 1,
    {
        let mut result: Vec<i32> = Vec::new();
        let len = a.len() as nat;
        let mut idx: nat = 0;

        while idx < len
            invariant
                idx <= len,
                result.len() == idx,
                forall |j: nat| 0 <= j < idx ==> result[j] == 1,
            decreases len - idx,
        {
            result.push(1);
            idx = idx + 1;
        }

        result
    }
}

